#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int stores, days;
    scanf("%d %d", &stores, &days);
    int *sales = malloc((size_t)stores * days * sizeof *sales);
    if (sales == NULL) {
        return 1;
    }
    for (int s = 0; s < stores; s++) {
        for (int d = 0; d < days; d++) {
            scanf("%d", &sales[s * stores + d]);
        }
    }
    for (int s = 0; s < stores; s++) {
        long long total = 0;
        for (int d = 0; d < days; d++) {
            total += sales[s * stores + d];
        }
        printf(s + 1 < stores ? "%lld " : "%lld\n", total);
    }
    for (int d = 0; d < days; d++) {
        long long total = 0;
        for (int s = 0; s < stores; s++) {
            total += sales[s * stores + d];
        }
        printf(d + 1 < days ? "%lld " : "%lld\n", total);
    }
    free(sales);
    return 0;
}

